// @zeus-internal
"use client";
import {
  useCallback,
  useEffect,
  useRef,
  useState,
  type CSSProperties,
  type ReactNode,
  type PointerEvent,
  type KeyboardEvent,
} from "react";
export interface GalleryInternalItem {
  id: string;
  src?: string;
  alt?: string;
  title?: string;
  description?: string;
  content?: ReactNode;
}
export interface GalleryInternalProps {
  items: readonly GalleryInternalItem[];
  index?: number;
  defaultIndex?: number;
  onChange?: (index: number) => void;
  onSelect?: (item: GalleryInternalItem, index: number) => void;
  renderCaption?: (item: GalleryInternalItem, index: number) => ReactNode;
  className?: string;
  style?: CSSProperties;
  label?: string;
  height?: number;
}
export const galleryWrap = (value: number, length: number) =>
  length > 0 ? ((value % length) + length) % length : 0;
export const galleryDistance = (index: number, phase: number, count: number) =>
  count > 0 ? galleryWrap(index - phase + count / 2, count) - count / 2 : 0;
const galleryControlTarget = (target: Element) =>
  target.closest(
    "[data-gallery-control], [data-gallery-content] :is(button, a, input, textarea, select, [contenteditable], [role=button])",
  );
export function useGalleryEnvironment() {
  const ref = useRef<HTMLDivElement>(null);
  const [size, setSize] = useState({ width: 1000, height: 640 });
  const [active, setActive] = useState(false);
  const [reduced, setReduced] = useState(false);
  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    let visible = true;
    const media = window.matchMedia("(prefers-reduced-motion: reduce)");
    const update = () => {
      setReduced(media.matches);
      setActive(visible && !document.hidden);
    };
    const resize = () => setSize({ width: el.clientWidth || 1000, height: el.clientHeight || 640 });
    resize();
    const ro = typeof ResizeObserver === "undefined" ? null : new ResizeObserver(resize);
    ro?.observe(el);
    const io =
      typeof IntersectionObserver === "undefined"
        ? null
        : new IntersectionObserver((entries) => {
            visible = entries[0]?.isIntersecting ?? true;
            update();
          });
    io?.observe(el);
    media.addEventListener("change", update);
    document.addEventListener("visibilitychange", update);
    update();
    return () => {
      ro?.disconnect();
      io?.disconnect();
      media.removeEventListener("change", update);
      document.removeEventListener("visibilitychange", update);
    };
  }, []);
  return { ref, size, active, reduced };
}
export function useGalleryIndex({
  items,
  index,
  defaultIndex = 0,
  onChange,
}: GalleryInternalProps) {
  const [value, setValue] = useState(defaultIndex);
  const current = galleryWrap(index ?? value, items.length);
  const choose = useCallback(
    (next: number) => {
      next = galleryWrap(next, items.length);
      if (index === undefined) setValue(next);
      if (next !== current) onChange?.(next);
    },
    [current, index, items.length, onChange],
  );
  return { current, choose };
}
export function useGalleryMotion(
  count: number,
  options: {
    index?: number;
    defaultIndex?: number;
    onChange?: (index: number) => void;
    drag?: boolean;
    autoplay?: boolean;
    speed?: number;
    sensitivity?: number;
    snap?: boolean;
    vertical?: boolean;
    pauseOnHover?: boolean;
  },
  environment: ReturnType<typeof useGalleryEnvironment>,
) {
  const {
    index,
    defaultIndex = 0,
    onChange,
    drag = true,
    autoplay = false,
    speed = 0.15,
    sensitivity = 220,
    snap = false,
    vertical = false,
    pauseOnHover = false,
  } = options;
  const [phase, setPhase] = useState(defaultIndex);
  const value = useRef(defaultIndex);
  const velocity = useRef(0);
  const target = useRef<number | null>(null);
  const pointer = useRef<{ id: number; position: number; time: number; distance: number } | null>(
    null,
  );
  const moved = useRef(false);
  const [hovered, setHovered] = useState(false);
  const [focused, setFocused] = useState(false);
  const [paused, setPaused] = useState(false);
  const [dragging, setDragging] = useState(false);
  const lastIndex = useRef(galleryWrap(Math.round(defaultIndex), count));
  const changeRef = useRef(onChange);
  changeRef.current = onChange;
  const commit = useCallback(
    (next: number) => {
      if (!Number.isFinite(next)) return;
      value.current = next;
      setPhase(next);
      const selected = galleryWrap(Math.round(next), count);
      if (lastIndex.current !== selected) {
        lastIndex.current = selected;
        changeRef.current?.(selected);
      }
    },
    [count],
  );
  const choose = useCallback(
    (next: number) => {
      if (index !== undefined) {
        changeRef.current?.(galleryWrap(Math.round(next), count));
        return;
      }
      velocity.current = 0;
      if (environment.reduced) {
        target.current = null;
        commit(next);
      } else target.current = next;
    },
    [commit, environment.reduced, index, count],
  );
  useEffect(() => {
    if (index !== undefined) {
      target.current = null;
      velocity.current = 0;
      value.current = index;
      setPhase(index);
      lastIndex.current = galleryWrap(Math.round(index), count);
    }
  }, [index, count]);
  useEffect(() => {
    if (!environment.active || environment.reduced || count < 1) return;
    let frame = 0,
      last = 0;
    const tick = (time: number) => {
      const dt = Math.min((time - (last || time)) / 1000, 0.04);
      last = time;
      if (!pointer.current) {
        if (target.current !== null) {
          const next = value.current + (target.current - value.current) * (1 - Math.exp(-dt * 12));
          if (Math.abs(next - target.current) < 0.0005) {
            commit(target.current);
            target.current = null;
          } else commit(next);
        } else {
          velocity.current *= Math.exp(-dt * 5);
          const drift = autoplay && !paused && !focused && !(pauseOnHover && hovered) ? speed : 0;
          if (Math.abs(velocity.current) > 0.0001 || drift)
            commit(value.current + (velocity.current + drift) * dt);
        }
      }
      frame = requestAnimationFrame(tick);
    };
    frame = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(frame);
  }, [
    environment.active,
    environment.reduced,
    count,
    autoplay,
    speed,
    paused,
    hovered,
    focused,
    pauseOnHover,
    commit,
  ]);
  const release = (event: PointerEvent<HTMLDivElement>) => {
    const p = pointer.current;
    if (!p || p.id !== event.pointerId) return;
    pointer.current = null;
    setDragging(false);
    if (event.currentTarget.hasPointerCapture?.(event.pointerId))
      event.currentTarget.releasePointerCapture(event.pointerId);
    if (environment.reduced) velocity.current = 0;
    if (snap) {
      const next = Math.round(value.current + velocity.current * 0.1);
      velocity.current = 0;
      choose(next);
    }
  };
  return {
    phase: index ?? phase,
    current: galleryWrap(Math.round(index ?? phase), count),
    choose,
    dragging,
    paused,
    setPaused: (next: boolean) => {
      setPaused(next);
      if (next) {
        velocity.current = 0;
        target.current = null;
      }
    },
    moved,
    handlers: {
      onPointerEnter: () => setHovered(true),
      onPointerLeave: () => setHovered(false),
      onFocus: (event: React.FocusEvent<HTMLDivElement>) =>
        setFocused(!galleryControlTarget(event.target as Element)),
      onBlur: (event: React.FocusEvent<HTMLDivElement>) => {
        if (!event.currentTarget.contains(event.relatedTarget)) setFocused(false);
      },
      onPointerDown: (event: PointerEvent<HTMLDivElement>) => {
        if (!drag || event.button !== 0 || galleryControlTarget(event.target as Element)) return;
        target.current = null;
        velocity.current = 0;
        moved.current = false;
        pointer.current = {
          id: event.pointerId,
          position: vertical ? event.clientY : event.clientX,
          time: performance.now(),
          distance: 0,
        };
        setDragging(true);
      },
      onPointerMove: (event: PointerEvent<HTMLDivElement>) => {
        const p = pointer.current;
        if (!p || p.id !== event.pointerId) return;
        const next = vertical ? event.clientY : event.clientX;
        const now = performance.now();
        const delta = -(next - p.position) / Math.max(1, sensitivity);
        p.distance += Math.abs(next - p.position);
        moved.current = p.distance > 5;
        if (moved.current && !event.currentTarget.hasPointerCapture(event.pointerId))
          event.currentTarget.setPointerCapture(event.pointerId);
        velocity.current = delta / Math.max(0.008, (now - p.time) / 1000);
        commit(value.current + delta);
        p.position = next;
        p.time = now;
      },
      onPointerUp: release,
      onPointerCancel: (event: PointerEvent<HTMLDivElement>) => {
        velocity.current = 0;
        release(event);
      },
      onKeyDown: (event: KeyboardEvent<HTMLDivElement>) => {
        if (event.key === "ArrowRight" || event.key === "ArrowDown") {
          event.preventDefault();
          choose(Math.round(value.current) + 1);
        } else if (event.key === "ArrowLeft" || event.key === "ArrowUp") {
          event.preventDefault();
          choose(Math.round(value.current) - 1);
        } else if (event.key === "Home") {
          event.preventDefault();
          choose(0);
        } else if (event.key === "End") {
          event.preventDefault();
          choose(count - 1);
        } else if (event.key === " " && event.target === event.currentTarget) {
          event.preventDefault();
          setPaused((v) => !v);
          setFocused(false);
        }
      },
    },
  };
}
export function GalleryInternalImage({
  item,
  style,
  className,
}: {
  item: GalleryInternalItem;
  style?: CSSProperties;
  className?: string;
}) {
  return item.content ? (
    <div className={className} style={style}>
      {item.content}
    </div>
  ) : item.src ? (
    <img
      className={className}
      src={item.src}
      alt={item.alt ?? item.title ?? ""}
      draggable={false}
      style={style}
    />
  ) : (
    <div
      className={className}
      style={{ ...style, background: "#d8d6d1", display: "grid", placeItems: "center" }}
    >
      {item.title}
    </div>
  );
}
export function GalleryInternalControls({
  current,
  count,
  onPrevious,
  onNext,
  paused,
  onPause,
}: {
  current: number;
  count: number;
  onPrevious: () => void;
  onNext: () => void;
  paused?: boolean;
  onPause?: () => void;
}) {
  return (
    <div className="z-ag-controls" data-gallery-control>
      <button type="button" aria-label="Previous item" disabled={count < 2} onClick={onPrevious}>
        ‹
      </button>
      <span className="z-ag-sr" role="status">
        {count ? current + 1 : 0} of {count}
      </span>
      <button type="button" aria-label="Next item" disabled={count < 2} onClick={onNext}>
        ›
      </button>
      {onPause && (
        <button
          type="button"
          aria-label={paused ? "Play animation" : "Pause animation"}
          aria-pressed={paused}
          onClick={onPause}
        >
          {paused ? "▷" : "Ⅱ"}
        </button>
      )}
    </div>
  );
}
export function GalleryInternalStyles() {
  return (
    <style>{`
.z-ag{position:relative;width:100%;height:var(--z-ag-height,640px);min-width:0;overflow:hidden;background:#eeedeb;color:#161616;font-family:Arial,sans-serif;isolation:isolate}.z-ag *{box-sizing:border-box}.z-ag button{font:inherit;color:inherit}.z-ag img{display:block;object-fit:cover;width:100%;height:100%;user-select:none}.z-ag button:focus-visible,.z-ag:focus-visible{outline:3px solid #ff5b2b;outline-offset:-3px}.z-ag-card{position:absolute;left:50%;top:50%;padding:0;border:0;background:none;overflow:hidden}.z-ag-controls{position:absolute;z-index:100;bottom:24px;left:50%;display:flex;gap:8px;transform:translateX(-50%);align-items:center}.z-ag-controls button{border:0;border-radius:6px;background:#d5d4d1;color:#151515;width:40px;height:40px;font-size:25px;cursor:pointer}.z-ag-controls button:disabled{opacity:.35}.z-ag-caption{position:absolute;left:24px;right:20px;bottom:24px;text-align:left;color:white;text-shadow:0 1px 14px #000;font-size:clamp(18px,2.2vw,32px);font-weight:600}.z-ag-hint{position:absolute;bottom:24px;left:24px;z-index:2;color:#969591;font-size:12px}.z-ag-sr{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}.z-ag-list{height:auto;min-height:var(--z-ag-height,640px);display:flex;flex-direction:column;justify-content:center}.z-ag-row{position:relative;display:flex;align-items:center;width:100%;min-height:70px;padding:22px 24px;text-align:left;border:0;border-top:1px solid #d7d6d4;background:transparent;cursor:pointer;overflow:hidden}.z-ag-row:last-child{border-bottom:1px solid #d7d6d4}.z-ag-row-label{position:relative;z-index:2;transition:transform .35s}.z-ag-row[data-active=true] .z-ag-row-label{transform:translateX(16px)}.z-ag-empty{position:absolute;inset:0;display:grid;place-items:center;color:#777}@media(max-width:600px){.z-ag{height:var(--z-ag-mobile-height,520px)}.z-ag-controls{bottom:16px}.z-ag-caption{left:15px;bottom:18px}.z-ag-list{height:auto;min-height:520px}.z-ag-row{min-height:64px;padding:20px 18px}}@media(prefers-reduced-motion:reduce){.z-ag *{transition-duration:0s!important;animation:none!important}}
`}</style>
  );
}
export const galleryStyle = (height: number, style?: CSSProperties) =>
  ({
    "--z-ag-height": `${height}px`,
    "--z-ag-mobile-height": `${Math.min(height, 560)}px`,
    ...style,
  }) as CSSProperties;

"use client";
import { useEffect, useRef, useState } from "react";
import { motion } from "motion/react";
import {
  GalleryInternalImage,
  GalleryInternalStyles,
  galleryStyle,
  useGalleryEnvironment,
  useGalleryIndex,
  type GalleryInternalProps,
  type GalleryInternalItem,
} from "./gallery-shared";
export interface IndexWipeItem extends GalleryInternalItem {}
export interface IndexWipeProps extends GalleryInternalProps {
  items: readonly IndexWipeItem[];
  duration?: number;
  dim?: number;
}
export function IndexWipe(props: IndexWipeProps) {
  const {
    items,
    duration = 0.85,
    dim = 0.45,
    height = 640,
    label = "Chapter index",
    className = "",
    style,
    onSelect,
  } = props;
  const env = useGalleryEnvironment();
  const { current, choose } = useGalleryIndex(props);
  const last = useRef(current);
  const [transition, setTransition] = useState({ previous: current, direction: 1 });
  useEffect(() => {
    if (last.current !== current) {
      setTransition({ previous: last.current, direction: current > last.current ? 1 : -1 });
      last.current = current;
    }
  }, [current]);
  const direction =
    current === last.current ? transition.direction : current > last.current ? 1 : -1;
  const previous = current === last.current ? transition.previous : last.current;
  const clip =
    direction > 0
      ? "polygon(0% 0%,100% 0%,100% 0%,0% -8%)"
      : "polygon(0% 108%,100% 100%,100% 100%,0% 100%)";
  return (
    <div
      ref={env.ref}
      className={`z-ag ${className}`}
      data-gallery="index-wipe"
      data-index={current}
      data-direction={direction}
      role="region"
      aria-label={label}
      style={galleryStyle(height, { background: "#111", color: "#fff", ...style })}
    >
      <GalleryInternalStyles />
      {items[previous] && (
        <GalleryInternalImage item={items[previous]} style={{ position: "absolute", inset: 0 }} />
      )}
      {items[current] && (
        <motion.div
          key={items[current].id}
          className="z-ag-wipe"
          initial={{ clipPath: clip }}
          animate={{ clipPath: "polygon(0% 0%,100% 0%,100% 100%,0% 100%)" }}
          transition={{ duration: env.reduced ? 0 : duration, ease: [0.76, 0, 0.24, 1] }}
          style={{ position: "absolute", inset: 0 }}
        >
          <GalleryInternalImage item={items[current]} />
        </motion.div>
      )}
      <div style={{ position: "absolute", inset: 0, background: `rgba(0,0,0,${dim})` }} />
      <span style={{ position: "absolute", right: 28, top: 30, fontSize: 13 }}>Index</span>
      <nav
        aria-label={label}
        style={{
          position: "absolute",
          left: "3.2%",
          top: "12%",
          bottom: "12%",
          display: "flex",
          flexDirection: "column",
          justifyContent: "center",
        }}
      >
        {items.map((item, i) => (
          <button
            type="button"
            key={item.id}
            data-gallery-card={i}
            aria-current={current === i ? "true" : undefined}
            onPointerEnter={(e) => {
              if (e.pointerType !== "touch") choose(i);
            }}
            onFocus={() => choose(i)}
            onClick={() => {
              choose(i);
              onSelect?.(item, i);
            }}
            style={{
              padding: 0,
              border: 0,
              background: "none",
              fontSize: "clamp(34px,6.7vw,88px)",
              lineHeight: 1.15,
              letterSpacing: "-.04em",
              fontWeight: 400,
              textAlign: "left",
              color: current === i ? "#fff" : "#ffffff50",
              cursor: "pointer",
              transition: `color ${duration / 2}s`,
            }}
          >
            {item.title}
          </button>
        ))}
      </nav>
      <div
        style={{
          position: "absolute",
          bottom: 28,
          left: "3.2%",
          fontSize: 13,
          display: "flex",
          gap: 4,
          overflow: "hidden",
          height: 16,
        }}
      >
        <motion.span
          key={current}
          initial={{ y: direction * 18 }}
          animate={{ y: 0 }}
          transition={{ duration: env.reduced ? 0 : duration }}
        >
          {String(current + 1).padStart(2, "0")}
        </motion.span>
        <span style={{ opacity: 0.5 }}>/ {String(items.length).padStart(2, "0")}</span>
      </div>
    </div>
  );
}
